// Colour parity between the browser and the engine (11.4).
//
// The done-when is "Colour ramp matches the engine render". What makes that
// provable rather than hopeful: the reference values in
// `transfer-reference.ts` were generated by the Rust functions in
// `Shared/contracts/src/color.rs`, and these tests assert the TypeScript
// curves match them to the last representable bit.
//
// The property under test is invariant 27 — two parallel implementations of
// one spec must change together. A curve edited on one side without the other
// fails here, at the same run as the rest of the gate, instead of failing a
// pixel comparison weeks later for a reason nobody traces to a transfer
// function.

import { describe, expect, it } from "vitest";

import {
  rec709Decode,
  rec709Encode,
  srgbDecode,
  srgbEncode,
} from "../src/color-transfer";
import { TRANSFER_REFERENCE } from "../src/transfer-reference";

describe("the browser's transfer curves match the engine's", () => {
  // The done-when is that a ramp matches the engine render, and the unit the
  // gate measures is an 8-bit channel. Rust's `powf` and JavaScript's
  // `Math.pow` are each correctly-rounded libm and can disagree by one ulp in
  // f64 — measured here at exactly one sample (0.7874122893956172 vs ...74).
  // One ulp of f64 is ~1e-16, which rounds to the same 8-bit channel by an
  // enormous margin, so bit-for-bit is not the contract the pixels need; the
  // last 8-bit value is. A tolerance any wider would accept drift this whole
  // exercise exists to forbid.
  //
  // The channel is the truth, the f64 is how we get there.
  const channel = (linear: number): number =>
    Math.max(0, Math.min(255, Math.round(linear * 255)));

  for (const sample of TRANSFER_REFERENCE) {
    it(`sRGB encode at ${sample.x} agrees to the 8-bit channel`, () => {
      expect(channel(srgbEncode(sample.x))).toBe(channel(sample.srgbEncode));
      expect(Math.abs(srgbEncode(sample.x) - sample.srgbEncode)).toBeLessThan(1e-12);
    });
    it(`sRGB decode at ${sample.x} agrees to the 8-bit channel`, () => {
      expect(channel(srgbDecode(sample.x))).toBe(channel(sample.srgbDecode));
      expect(Math.abs(srgbDecode(sample.x) - sample.srgbDecode)).toBeLessThan(1e-12);
    });
    it(`Rec.709 encode at ${sample.x} agrees to the 8-bit channel`, () => {
      expect(channel(rec709Encode(sample.x))).toBe(channel(sample.rec709Encode));
      expect(Math.abs(rec709Encode(sample.x) - sample.rec709Encode)).toBeLessThan(1e-12);
    });
    it(`Rec.709 decode at ${sample.x} agrees to the 8-bit channel`, () => {
      expect(channel(rec709Decode(sample.x))).toBe(channel(sample.rec709Decode));
      expect(Math.abs(rec709Decode(sample.x) - sample.rec709Decode)).toBeLessThan(1e-12);
    });
  }

  it("sRGB round-trips through encode and decode", () => {
    // A ramp is the exact case where drift is visible: a gradient composited
    // in one space and read in another steps visibly in the shadows.
    for (let i = 0; i <= 256; i += 1) {
      const linear = i / 256;
      const encoded = srgbEncode(linear);
      expect(srgbDecode(encoded)).toBeCloseTo(linear, 12);
    }
  });

  it("Rec.709 round-trips through encode and decode", () => {
    for (let i = 0; i <= 256; i += 1) {
      const linear = i / 256;
      expect(rec709Decode(rec709Encode(linear))).toBeCloseTo(linear, 12);
    }
  });
});
